from collections import defaultdict

def count_disjoint_paths(edges, n):
    # Build adjacency list for the tree
    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    # DFS function to count paths in each subtree
    def dfs(node, parent, depth):
        for child in tree[node]:
            if child != parent:
                dfs(child, node, depth + 1)
                paths += depth * (nodes - 1 - depth) + depth

    nodes = 1  # Start from the root node
    for node in tree:
        for child in tree[node]:
            if child not in tree:
                nodes += 1
    nodes -= 1  # Correcting for the root node

    paths = 0
    dfs(1, -1, 0)

    q = defaultdict(int)
    for i in range(1, nodes + 1):
        if q[i] != 0:
            paths += q[i] * (nodes - 1 - q[i])
        cur = defaultdict(int)
        for j in q.keys():
            q[j] -= q[i]
            on_q = q[i] + q[j]
            q[i] = cur[j] = 0
            if on_q not in q:
                q[on_q] = on_q
            if i == j or i == on_q:
                continue
            exist = any([k in q and i + on_q in q for k in q.keys() if k != i and k not in [i, j]])
            occur = any([k in q and i in q and k < on_q + 1 and i < on_q + 1 for k in q.keys() if k != i and k not in [i, j]])
            exists = exist or occur
            if exists:
                q[i] += q[on_q] + 1
                cur[i] = i + on_q
                cur[on_q] = i + 1
        for k in cur.keys():
            if cur[k] not in cur:
                cur[cur[k]] = k
        if i in q:
            q[i] = cur[i]

    return paths

