def solve(n, queries):
    memo = {}

    def is_exterminable(i, j):
        if j < 0:
            return 0

        if (i, j) in memo:
            return memo[(i, j)]

        if i == 0:
            return 1

        if j == 0:
            return -1

        push, top = queries[i], queries[i - 1]

        if top >= push:
            memo[(i, j)] = max(is_exterminable(i + 1, j + 1), is_exterminable(i + 1, j)) + 1
        else:
            memo[(i, j)] = max(is_exterminable(i + 1, j + 1), is_exterminable(i + 1, j - 1))

        return memo[(i, j)]

    result = 0
    for i in range(len(queries)):
        result += is_exterminable(i + 1, 0)

    return result

