def construct_new_graph(n, m, edges):
    # Check if it's possible to construct the new graph
    if n > m:
        return [-1]

    # Create a graph and stores the adjacency list of the nodes
    graph = [[] for _ in range(n)]
    visited = [False] * n
    in_degree = [0] * n

    for u, v in edges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)
        in_degree[u-1] += 1
        in_degree[v-1] += 1

    # Process the nodes with zero in-degree, which are leaf nodes
    leaf_nodes = []
    for i in range(n):
        if in_degree[i] == 1:
            leaf_nodes.append(i)

    # De-duplicate nodes in the adjacency list of leaf nodes
    for node in leaf_nodes:
        leaf_nodes.extend(graph[node])

    if len(leaf_nodes) != n:
        return [-1]

    # Traverse the tree structure to construct the new graph
    stack = []
    for i in range(n):
        if in_degree[i] == 1 and not visited[i]:
            stack.append(i)

    if not stack:
        return [-1]

    while stack:
        curr_node = stack.pop()
        visited[curr_node] = True
        for neighbor in graph[curr_node]:
            if not visited[neighbor]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 1:
                    stack.append(neighbor)

    # Create the new graph
    new_edges = []
    for i in range(n):
        for neighbor in graph[i]:
            if not visited[neighbor]:
                new_edges.append((i+1, neighbor + 1))  # Adjusting to 1-based indexing

    return new_edges

