            if (n >> (7-j)) & 1:
                flat_number += g
                for k in range(j):
                    flat_number += e >> k & 1
                    for l in range(k+1):
                        flat_number += b >> (l-k) & 1
                    for m in range(l):
                        flat_number += c >> (m-l) & 1
                        for n in range(m):
                            flat_number += a >> (n-m) & 1
            else:
                flat_number = flat_number | 1 << j
            accumulative_number = 0
            while (flat_number - 1) // 2**i >= 0:
                accumulative_number += (flat_number - 1) // 2**i
                flat_number //= 2**i
            coins += a + b + c + d + flat_number * e + accumulative_number * f
        if coins < min_coins:
            min_coins = coins
    return min_coins

