def is_match(address: str, net: str) -> bool:
    segments = address.split('.')
    net_segments = net.split('.')
    for a, b in zip(segments, net_segments):
        if len(a) > len(b):
            return False
        for i in range(16):
            if (int(a, 16) ^ int(b, 16)) & (1 << (i - 1)):
                return False
            if (a[i] != '0' and a[i] != b[i]):
                return False
    return True

def find_packets(address: str, nets: List[str]) -> bool:
