        segments = net.split('.')
        net_value = 0
        for i in range(4):
            net_value |= (int(segments[i]) if segments[i] != '0.0.0.0/32' else 0) << (16 - (3 - i))

        if segments[2] == '/32':
            continue  # Skip /32 networks as they are already isolated sets

        leftmost_bits = 32 - len(segments[2]) + 1
        rightmost_bits = int(segments[2]) == net_value

