def max_score(N, M, T, events):
    a, b = 0, 0
    result = 0
    score_history = [0] * max(M, N)
    events_heap = [(0, a, 0)]
    for event in events:
        time, type, count = event
        if type == 1:
            if a > b:
                score_history[len(score_history) - 1] += 1
            elif score_history[time - T] > score_history[time - T + 1]:
                a, b, count = 0, 0, 0
        else:
            if a < b:
                score_history[len(score_history) - 1] += 1
            elif score_history[time - T] > score_history[time - T + 1]:
                a, b, count = 0, 0, 0
        # Add the event back into the heap
        heappush(events_heap, (-time + ((len(score_history) - 1) % 2) * 5, a, b, count))

    for i in range(N):
        result += score_history[i]
    return result

