def detect_loops(graph):
    visited = set()
    for node in graph:
        if node in visited:
            continue
        if detect_cycle_helper(node, graph, -1, visited):
            return True
    return False

def detect_cycle_helper(node, graph, parent, visited):
    visited.add(node)
    for neighbor in graph[node]:
        if neighbor == parent:
            continue
        if neighbor in visited or detect_cycle_helper(neighbor, graph, node, visited):
            return True
    return False

def sort_edges(graph):
    processed_nodes = set()
    result = []
    for node in graph:
        if node not in processed_nodes:
            for neighbor in graph[node]:
                if neighbor not in processed_nodes:
                    result.append((node, neighbor))
                    processed_nodes.add(neighbor)
                    processed_nodes.add(node)
    return result

def possible_new_graph(n, edges):
    if n % 2 != 0:
        return -1

    graph = defaultdict(list)
    min_num_edges = n

    for u, v in edges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)
        if len(graph[u-1]) == n or len(graph[v-1]) == n:
            min_num_edges = min(min_num_edges, len(graph[u-1]))
            min_num_edges = min(min_num_edges, len(graph[v-1]))

    if min_num_edges != n:
        return -1

    return sort_edges(graph)

