import sys

def dfs(node, parent, distances, group_sizes, count, paths, zero, one, two, three):
    paths[node] = count
    zero[node] = paths[node][3] != 0
    one[node] = paths[node][3] == paths[node][4] and paths[node][0] != 0 and paths[node][1] != 0 and paths[node][2] != 0
    two[node] = paths[node][3] == paths[node][4] and paths[node][0] != 0 and paths[node][1] != 0 and paths[node][2] == 0
    three[node] = paths[node][3] == paths[node][4] and paths[node][0] != 0 and paths[node][1] == 0 and paths[node][2] == 0

    for neighbor in distances[node]:
        if neighbor == parent:
            continue
        group_sizes[node] += dfs(neighbor, node, distances, group_sizes, count + (paths[node][1] - paths[node][0] + 1), paths, zero, one, two, three)
        paths[node][3] += group_sizes[node]
        paths[node][4] += group_sizes[node]
        paths[node][0] = paths[node][1] = paths[node][2] = paths[node][3] = paths[node][4] = 0

def calculate_3(node, parent, connectivity):
    for neighbor in distances[node]:
        if neighbor == parent:
            continue
        paths[node][3] += calculate_3(neighbor, node, connectivity)

def calculate_4(node, parent, connectivity):
    for neighbor in distances[node]:
        if neighbor == parent:
            continue
        paths[node][4] += calculate_4(neighbor, node, connectivity)

def calculate_2(node, parent, connectivity):
    for neighbor in distances[node]:
        if neighbor == parent:
            continue
        paths[node][2] += calculate_2(neighbor, node, connectivity)

def calculate_1(node, parent, connectivity):
    for neighbor in distances[node]:
        if neighbor == parent:
            continue
        paths[node][1] += calculate_1(neighbor, node, connectivity)

def solve(n, edges):
    if n == 1:
        return 1

    phy = [0] * (1 << n)
    phy[0] = 1
    for i in range(n-1):
        phy[edges[i][0] + (1 << (edges[i][1] - 1))] += phy[edges[i][1] + (1 << (edges[i][1] - 1))]

    distances = [[] for _ in range(n)]
    connectivity = [[1] * n for _ in range(1 << n)]
    group_sizes = [[0, 0, 0, 0] for _ in range(n)]
    min_paths = [[2 * 2 * n + 1, 1, 0, 0] for _ in range(n)]
    for edge in edges:
        distances[edge[0]].append(edge[1])
        distances[edge[1]].append(edge[0])

    for bit in range(1 << n):
        path_length = min_paths[bit][0]
        if path_length > n // 2:
            continue
        path_count = 1
        occ_dist = bit
        edges_cnt = 0
        for i in range(n):
            if bit >> i & 1:
                edges_cnt += phy[occ_dist]
            occ_dist = min(occ_dist + distances[i][path_length - 1], n - 1)
            if bit >> i & 1:
                path_count += phy[occ_dist]
        min_paths[bit] = [path_length, path_count, edges_cnt, phy[bit]]

    zero, one, two, three = [-1] * n, [-1] * n, [-1] * n, [-1] * n

    groups = []
    for i in range(n):
        groups.append([i, group_sizes[i][0] + group_sizes[i][1] + group_sizes[i][2] + group_sizes[i][3]])
        calculate_1(i, -1, group_sizes[i] + group_sizes)
        calculate_2(i, -1, group_sizes[i] + group_sizes)
        calculate_3(i, -1, group_sizes[i] + group_sizes)
        calculate_4(i, -1, group_sizes[i] + group_sizes)
    x = groups
    group = [[0] * 6 for _ in range(1 << n)]
    for i in range(1 << n):
        for j in range(n):
            if i >> j & 1:
                group[i][0] += x[j][0]
                group[i][1] += x[j][1]
                group[i][2] += x[j][2]
                group[i][3] += x[j][3]
                group[i][4] += x[j][4]
                group[i][5] += x[j][5]
    prefix_sum = [[0] * 6 for _ in range(1 << n)]
    for j in range(n):
        for i in range(1 << n):
            prefix_sum[i][0] += group[i][0]
            prefix_sum[i][1] += group[i][1]
            prefix_sum[i][2] += group[i][2]
            prefix_sum[i][3] += group[i][3]
            prefix_sum[i][4] += group[i][4]
            prefix_sum[i][5] += group[i][5]
    count = 0
    for i in range(1 << n):
        if (prefix_sum[i][1] - prefix_sum[i][0] != 0):
            count += phy[i]
    single = count // 3
    triple = (n*n + 2*n + 1) - single
    return (single*triple + single*(single-1)//2 + single*(n-single) + triple*(triple-1)//2 + triple*(n-triple))

