def dfs(index, sequence, G, visited):
    length = len(sequence)
    if length > M and G[sequence[index]] < length and visited[index]:
        return 0
    if length > M or not sequence or G.get(sequence[index] - gcd(sequence[index], sequence[length - 1])) < length:
        return 0
    if index == length - 1:
        return 1
    cnt = 0
    next_G = G[sequence[index]]
    for j in range(index + 1, length):
        L = lcm(M, sequence[j]) - sequence[j]
        if L < next_G:
            cnt += dfs(j, sequence[:j] + [G[sequence[j]], L] + sequence[j + 1:], G, visited + [(j, L)])
    return cnt % 1000000007

