def create_partitions(N, M):
    k = 1
    partitions = []
    for i in range(2, N + 1):
        partition = [i] * N
        fixed_nodes = set()
        for j in range(2, M + 1):
            if k % 2 == 0:
                fixed_nodes.add(k // 2)
            else:
                fixed_nodes.add(k + N - k // 2)
            for node in fixed_nodes:
                partition[node - 1] = k % 2
            k += 1
        partitions.append(np.array(partition).reshape(N, 1))
    return partitions

